import{currencyDefaults,CURRENCIES}from './currency.js';
import{DEFAULTS,STRATEGIES,validate}from './engine.js';
import{parseCSV,vcmmRate,CSV_TEMPLATE}from './data.js';
import{fanChart,barChart,rateChart,money,pct}from './charts.js';
const $=id=>document.getElementById(id);
const fractionFields=new Set(['rate','cagr','vol','fee','drag','inflation','inflationVol','usWeight','longRun','guard','adjust','ceiling','floor','spendingFloor','successTarget']);
const stringFields=new Set(['currency','strategy','returnMode','sampling','inflationModel','successMetric']);
let selectedStrategy=null;
let dataset=null,last=null,swr=null,busy=false,worker=null,job=0,activeJob=null,db=null,comparisons=null,assumptions=null;
const descriptions={fixed:'每年維持初始生活費的購買力，支出穩定但可能耗盡資產。',percent:'按當年資產提領固定比例，支出跟著市場變化，生活費可能大幅縮水。',gk:'依護欄加減支出；全股票改編，最後 15 年停用減碼護欄。',dynamic:'以資產比例決定目標支出，限制每年實質調幅，仍可能耗盡資產。'};
function config(){const c={};for(const k of Object.keys(DEFAULTS)){const e=$(k);c[k]=stringFields.has(k)?e.value:Number(e.value)/(fractionFields.has(k)?100:1);}return c;}
function fill(c){for(const[k,v]of Object.entries(c))if($(k))$(k).value=fractionFields.has(k)?Number((v*100).toPrecision(12)):v;sync();}
function sync(){const c=config();
  const label=CURRENCIES[c.currency].label;
  $('initialCurrency').textContent=c.currency;
  $('planCurrency').textContent=c.currency;
  $('purchasingPowerLabel').textContent=label+'購買力基準';
  $('currencyHint').textContent='切換幣種會套用該幣種的資產與通膨預設。'+(c.currency==='TWD'?'股票報酬以美元估計，假設美元兌台幣匯率不變；未模擬匯率風險。':'股票報酬與購買力皆以美元計。');
  const historicalInflation=$('inflationModel').querySelector('[value="historical"]');
  historicalInflation.disabled=c.currency==='TWD';
  if(c.currency==='TWD'&&c.inflationModel==='historical'){$('inflationModel').value='constant';c.inflationModel='constant';}
  const hasDetails=['gk','dynamic'].includes(c.strategy);
  $('strategyDetails').hidden=!hasDetails;
  if(selectedStrategy!==c.strategy)$('strategyDetails').open=hasDetails;
  selectedStrategy=c.strategy;
  for(const [strategy,group,fields] of [['gk','gkFields',['guard','adjust']],['dynamic','dynamicFields',['ceiling','floor']]]){
    $(group).hidden=c.strategy!==strategy;
    for(const id of fields){
      if(c.strategy!==strategy&&(!Number.isFinite(c[id])||c[id]<Number($(id).min)/100||c[id]>Number($(id).max)/100)){$(id).value=DEFAULTS[id]*100;c[id]=DEFAULTS[id];}
      $(id).disabled=c.strategy!==strategy;
    }
  }
$('customFields').hidden=c.returnMode!=='custom';$('vcmmFields').hidden=c.returnMode!=='vcmm';$('volField').hidden=c.sampling!=='parametric';$('blockField').hidden=c.sampling!=='stationary';$('inflationVolField').hidden=c.inflationModel!=='lognormal';$('inflation').disabled=c.inflationModel==='historical';$('strategyHint').textContent=descriptions[c.strategy];$('vcmmAnchor').textContent=pct(vcmmRate(c.usWeight),3);if(!last){$('terminalNote').textContent='以退休起點的'+label+'購買力計';$('spendingMetric').textContent=money(c.initial*c.rate,false,c.currency);$('spendingNote').textContent=`每月約 ${money(c.initial*c.rate/12,false,c.currency)} · 稅前`;$('horizon').textContent=`${c.years} 年`;}$('parameters').classList.toggle('dirty',!!last);if(last)$('statusText').textContent='參數已更動；圖表保留上次執行結果，請重新模擬。';try{localStorage.setItem('retirement-config-v2',JSON.stringify(c));}catch{}}
function showTab(name){document.querySelectorAll('.tab-panel').forEach(el=>el.hidden=el.id!==name);document.querySelectorAll('[data-tab]').forEach(el=>{el.classList.toggle('active',el.dataset.tab===name);el.setAttribute('aria-selected',el.dataset.tab===name?'true':'false');});if(name==='dashboard')draw();if(name==='safe'&&swr)rateChart($('swrChart'),swr.result.trials,swr.result.target);}
function err(message){$('error').textContent=message;$('error').hidden=false;}
function setBusy(value){busy=value;$('fields').disabled=value;for(const id of ['compareRun','assumptionRun','swrRun','csvUpload','clearData','successTarget','successMetric','spendingFloor'])$(id).disabled=value;$('cancel').hidden=!value;$('progress').hidden=!value;$('status').classList.toggle('busy',value);}
function newWorker(){worker=new Worker(new URL('./worker.js',import.meta.url),{type:'module'});worker.onmessage=({data:m})=>{if(m.id!==activeJob?.id)return;if(m.type==='progress'){$('progress').value=m.value;$('statusText').textContent=`${m.label} · ${pct(m.value,0)}`;return;}if(m.type==='error'){err(m.message);setBusy(false);$('statusText').textContent='運算未完成，請檢查資料與參數。';activeJob=null;return;}const c=activeJob.config;setBusy(false);$('statusText').textContent=`計算完成 · ${(m.elapsed/1000).toFixed(2)} 秒 · ${c.paths.toLocaleString()} 條路徑 · 種子 ${c.seed}`;if(m.action==='run'){last={result:m.result,config:c,elapsed:m.elapsed,timing:{marketMs:m.marketMs,marketCached:m.marketCached},at:new Date().toISOString(),data:dataset?{name:dataset.name,kind:dataset.kind,from:dataset.dates[0],to:dataset.dates.at(-1),stats:dataset.stats}:null};$('parameters').classList.remove('dirty');render();}if(m.action==='compare')renderComparison(m.result,c,m.elapsed);if(m.action==='assumptions')renderAssumptions(m.result,c,m.elapsed);if(m.action==='swr'){swr={result:m.result,config:c};renderSWR();}activeJob=null;};worker.onerror=e=>{err('Worker 執行失敗：'+e.message);setBusy(false);worker.terminate();worker=null;activeJob=null;};}
function start(action){if(busy)return;$('error').hidden=true;const c=config();try{validate(c,dataset);}catch(e){err(e.message);if(!dataset&&c.returnMode==='historical')showTab('data');return;}if(!worker)newWorker();activeJob={id:++job,config:c};setBusy(true);$('progress').value=0;$('statusText').textContent='準備瀏覽器運算…';if(action==='run'){showTab('dashboard');document.querySelector('.sidebar').classList.remove('open');}worker.postMessage({id:job,action,config:c,dataset});}
function render(){const{result:r,config:c,elapsed}=last;$('ruinMetric').textContent=pct(1-r.survival);$('ruinNote').textContent=`95% 區間 ${pct(1-r.survivalCI[1])}–${pct(1-r.survivalCI[0])} · ${r.ruined.toLocaleString()} 條路徑`;$('lifestyleMetric').textContent=pct(r.lifestyle);$('lifestyleNote').textContent=`未耗盡，且各年生活費 ≥ 初始 ${pct(c.spendingFloor,0)}`;$('terminalMetric').textContent=money(r.terminal[3],true,c.currency);$('terminalNote').textContent=`${c.currency} 購買力 · P5 ${money(r.terminal[1],true,c.currency)} · P95 ${money(r.terminal[5],true,c.currency)}`;$('spendingMetric').textContent=money(c.initial*c.rate,false,c.currency);$('spendingNote').textContent=`每月約 ${money(c.initial*c.rate/12,false,c.currency)} · 本次模擬`;$('horizon').textContent=`${c.years} 年`;
  $('riskBars').replaceChildren();[10,20,30,50].forEach((d,i)=>{const row=document.createElement('div');row.className='risk-row';const title=document.createElement('span');title.textContent=`下降 >${d}%`;const track=document.createElement('div');track.className='risk-track';const bar=document.createElement('div');bar.className='risk-fill';bar.style.width=`${r.drops[i]*100}%`;track.append(bar);const value=document.createElement('b');value.textContent=pct(r.drops[i]);row.append(title,track,value);$('riskBars').append(row);});
  $('viewYears').max=c.years;$('viewYears').value=c.years;$('yearInspect').max=c.years;$('yearInspect').value=Math.min(25,c.years);$('yearOutput').textContent=`第 ${$('yearInspect').value} 年`;
  $('depletionSubtitle').textContent=r.medianDepletion?`耗盡路徑的首次耗盡年度中位數：第 ${r.medianDepletion} 年`:'這批路徑未發生耗盡；不代表未來不會發生。';
  $('runMeta').textContent=`${c.currency} · ${STRATEGIES[c.strategy]} · ${c.years} 年 × ${c.paths.toLocaleString()} 路徑 · ${(elapsed/1000).toFixed(2)} 秒 · ${c.returnMode==='historical'?'匯入歷史':c.returnMode==='vcmm'?'VCMM 參考情境':'自訂假設'} · ${c.sampling} · 種子 ${c.seed}`;
  $('exportCSV').disabled=false;$('exportJSON').disabled=false;draw();}
function draw(inspect=null){if(!last||$('dashboard').hidden)return;const{result:r,config:c}=last,years=Math.max(1,Math.min(c.years,Number($('viewYears').value)||c.years));document.querySelector('.primary-chart h2').textContent=`${c.years} 年後的你，可能站在哪裡？`;const sampleView=$('pathView').value==='samples';document.querySelector('.legend').innerHTML=sampleView?'<span class="key sample-best">期末最好樣本</span><span class="key sample-worst">期末最差樣本</span><span class="key median">P50 中位數</span>':'<span class="key pale">P5–P95</span><span class="key mid">P25–P75</span><span class="key median">P50 中位數</span>';$('yearInspect').max=years;$('yearOutput').textContent=`第 ${$('yearInspect').value} 年`;fanChart($('assetChart'),r.assetPercentiles,{currency:c.currency,tails:$('tails').checked,log:$('logScale').checked,initial:c.initial,years,samples:sampleView?r.samples:null,inspect,onYear:y=>{$('yearInspect').value=y;$('yearOutput').textContent=`第 ${y} 年`;}});fanChart($('spendingChart'),r.spendingPercentiles,{currency:c.currency,initial:c.initial*c.rate,years,spending:true,inspect:inspect===null?null:Math.max(1,inspect)});barChart($('histogram'),r.histogram,{N:c.paths,formatX:v=>money(v,true,c.currency),xlabel:'期末實質資產直方圖'});barChart($('depletionChart'),r.depletion.slice(1).map((count,i)=>({low:i+1,count})),{N:c.paths,formatX:v=>`${v}年`,xlabel:'首次耗盡年度'});}
function addRow(tbody,values){const tr=document.createElement('tr');values.forEach(v=>{const td=document.createElement('td');td.textContent=v;tr.append(td);});tbody.append(tr);}
function renderComparison(rows,c,elapsed){comparisons={rows,config:c};$('compareTable').replaceChildren();for(const r of rows)addRow($('compareTable'),[STRATEGIES[r.strategy],pct(1-r.survival),pct(r.lifestyle),pct(r.drops[1]),pct(r.drops[3])]);$('compareMeta').textContent=`本次：初始 ${money(c.initial,false,c.currency)} · ${pct(c.rate)} · ${c.years} 年 · ${c.paths.toLocaleString()} 路徑 · 生活費底線 ${pct(c.spendingFloor,0)} · ${c.returnMode} / ${c.sampling} · ${(elapsed/1000).toFixed(2)} 秒。`}
function renderAssumptions(rows,c,elapsed){assumptions={rows,config:c};$('assumptionTable').replaceChildren();for(const r of rows)addRow($('assumptionTable'),[r.label,pct(1-r.survival),pct(r.lifestyle),pct(r.drops[1])]);$('assumptionMeta').textContent=`${STRATEGIES[c.strategy]} · ${pct(c.rate)} · ${c.years} 年 · ${c.paths.toLocaleString()} 路徑 · 種子 ${c.seed} · ${(elapsed/1000).toFixed(2)} 秒。${dataset?'全部使用相同歷史抽樣索引；比較漂移差異。':'全部使用相同參數模型隨機衝擊；尚無歷史序列。'}`;}
function renderSWR(){const{result:r,config:c}=swr;$('swrValue').textContent=r.rate===null?'未達標':pct(r.rate);$('swrNote').textContent=`${STRATEGIES[c.strategy]} · ${c.years} 年 · ${c.paths.toLocaleString()} 路徑。`+(r.boundary?'已觸及 15% 上界，無法確定最高值。':r.rate===null?'0.1%–15% 的網格均未通過條件。':'網格精度 0.1 個百分點；非未來保證。')+(c.strategy==='percent'&&c.successMetric==='survival'?' 固定比例僅看存續不具經濟意義，建議加入生活費底線。':'');rateChart($('swrChart'),r.trials,r.target);}
function download(name,body,type){const url=URL.createObjectURL(new Blob([body],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),2000);}
async function openDB(){return new Promise((resolve,reject)=>{const req=indexedDB.open('retirement-lab-v1',1);req.onupgradeneeded=()=>req.result.createObjectStore('data');req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error);});}
async function dbGet(){if(!db)return null;return new Promise((resolve,reject)=>{const req=db.transaction('data').objectStore('data').get('dataset');req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error);});}
async function dbPut(value){if(!db)throw Error('本機儲存不可用；資料只保留在本次頁面。');return new Promise((resolve,reject)=>{const tx=db.transaction('data','readwrite');const store=tx.objectStore('data');value?store.put(value,'dataset'):store.delete('dataset');tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);});}
function dataSummary(){const el=$('datasetSummary');el.replaceChildren();$('dataNotice').replaceChildren();const div=document.createElement('div');if(!dataset){el.textContent='目前沒有匯入資料。可先使用自訂或 VCMM 參考情境。';const b=document.createElement('b');b.textContent='尚未載入 MSCI 歷史資料';const p=document.createElement('p');p.textContent='自訂與 VCMM 模式使用清楚標示的研究假設；沒有虛構或替代的 MSCI 時序。';div.append(b,p);}else{const s=dataset.stats;const b=document.createElement('b');b.textContent=dataset.name;const p=document.createElement('p');p.textContent=`${dataset.dates[0]} — ${dataset.dates.at(-1)} · ${s.months} 個月報酬 · ${dataset.kind==='fund-net'?'ETF 淨報酬（不重扣基金費）':'指數淨總報酬（另扣基金費）'} · ${dataset.inflation.length?'含 CPI／通膨':'未含 CPI'}`;el.append(b,p);const chips=document.createElement('div');chips.className='stat-chips';for(const[label,value]of [['歷史 CAGR',pct(s.cagr,2)],['月算術均值 ×12',pct(s.arithmeticAnnual,2)],['年化對數波動',pct(s.logVol,2)],['對數月報酬 lag-1 相關',s.autocorrelation.toFixed(3)]]){const chip=document.createElement('div'),title=document.createElement('span'),val=document.createElement('b');title.textContent=label;val.textContent=value;chip.append(title,val);chips.append(chip);}el.append(chips);for(const w of dataset.warnings){const p=document.createElement('p');p.textContent=w;el.append(p);}const title=document.createElement('b');title.textContent=`本機資料已載入：${dataset.name}`;const note=document.createElement('p');note.textContent=`${s.months} 個月 · ${dataset.dates[0]} — ${dataset.dates.at(-1)}。請確認 USD、Net Total Return、來源與使用權。`;div.append(title,note);}$('dataNotice').append(div);const btn=document.createElement('button');btn.className='outline';btn.textContent=dataset?'查看資料':'匯入 CSV';btn.onclick=()=>showTab('data');$('dataNotice').append(btn);}
document.querySelectorAll('[data-tab]').forEach(e=>e.onclick=()=>showTab(e.dataset.tab));$('methodsNav').onclick=()=>showTab('data');$('uploadNav').onclick=()=>showTab('data');$('mobileParams').onclick=()=>document.querySelector('.sidebar').classList.toggle('open');document.addEventListener('click',e=>{if(!e.target.closest('.sidebar')&&!e.target.closest('#mobileParams'))document.querySelector('.sidebar').classList.remove('open');});
$('parameters').onsubmit=e=>{e.preventDefault();start('run');};$('parameters').addEventListener('input',()=>{sync();});$('returnMode').addEventListener('change',()=>{if($('returnMode').value==='historical'){$('sampling').value='stationary';}sync();});$('sampling').addEventListener('change',()=>{if($('sampling').value==='parametric'&&$('returnMode').value==='historical')$('returnMode').value='custom';sync();});
$('currency').addEventListener('change',()=>{const preset=currencyDefaults($('currency').value);fill({...config(),initial:preset.initial,inflation:preset.inflation,inflationVol:preset.inflationVol,inflationModel:'constant'});});
$('reset').onclick=()=>fill(currencyDefaults($('currency').value));$('cancel').onclick=()=>{worker?.terminate();worker=null;activeJob=null;setBusy(false);$('statusText').textContent='已停止運算；保留上次完成的結果。';};$('compareRun').onclick=()=>start('compare');$('assumptionRun').onclick=()=>start('assumptions');$('swrRun').onclick=()=>start('swr');
for(const id of ['successTarget','successMetric','spendingFloor'])$(id).addEventListener('input',sync);
for(const id of ['tails','logScale','pathView'])$(id).addEventListener('change',()=>draw());$('viewYears').oninput=()=>draw();$('yearInspect').oninput=()=>{$('yearOutput').textContent=`第 ${$('yearInspect').value} 年`;draw(+$('yearInspect').value);};
$('template').onclick=()=>download('monthly-data-template.csv',CSV_TEMPLATE,'text/csv;charset=utf-8');
$('csvUpload').onchange=async e=>{const file=e.target.files[0];if(!file)return;$('error').hidden=true;if(file.size>10*1024*1024){err('CSV 超過 10 MB。');return;}try{const parsed=parseCSV(await file.text(),{name:$('datasetName').value.trim()||file.name,kind:$('datasetKind').value});dataset=parsed;try{await dbPut(dataset);}catch(e){err(e.message);}dataSummary();$('returnMode').value='historical';$('sampling').value='stationary';if(dataset.inflation.length)$('inflationModel').value='historical';else if($('inflationModel').value==='historical')$('inflationModel').value='constant';sync();$('statusText').textContent='資料已匯入，請執行模擬。';}catch(e){err(e.message);}e.target.value='';};
$('clearData').onclick=async()=>{dataset=null;try{await dbPut(null);}catch(e){err(e.message);}worker?.terminate();worker=null;if($('returnMode').value==='historical')$('returnMode').value='custom';$('sampling').value='parametric';if($('inflationModel').value==='historical')$('inflationModel').value='constant';dataSummary();sync();$('statusText').textContent='本機月資料已清除；已完成的研究結果仍保留在本次頁面。';};
$('exportJSON').onclick=()=>{if(!last)return;download('retirement-research-snapshot.json',JSON.stringify({version:'1.1.0',environment:{userAgent:navigator.userAgent,hardwareConcurrency:navigator.hardwareConcurrency,viewport:{width:innerWidth,height:innerHeight}},...last,comparisons,assumptions,swr,notice:'No raw historical observations included. Model-conditional simulations, not forecasts or guarantees.'},null,2),'application/json');};
$('exportCSV').onclick=()=>{if(!last)return;const r=last.result,currency=last.config.currency,lines=['year,currency,asset_p1,asset_p5,asset_p25,asset_p50,asset_p75,asset_p95,asset_p99,spend_p1,spend_p5,spend_p25,spend_p50,spend_p75,spend_p95,spend_p99'];r.assetPercentiles.forEach((a,i)=>{const sp=i===0?Array(7).fill(''):r.spendingPercentiles[i-1].values;lines.push([i,currency,...a.values,...sp].join(','));});download('retirement-real-'+currency.toLowerCase()+'-percentiles.csv',lines.join('\n'),'text/csv;charset=utf-8');};
let resizeTimer;window.addEventListener('resize',()=>{clearTimeout(resizeTimer);resizeTimer=setTimeout(()=>{draw();if(swr&&!$('safe').hidden)renderSWR();},120);});
try{
  const current=localStorage.getItem('retirement-config-v2');
  const legacy=current?null:JSON.parse(localStorage.getItem('retirement-config-v1'));
  const saved=current?JSON.parse(current):legacy?{...legacy,currency:'USD'}:null;
  fill(saved?{...currencyDefaults(saved.currency||'TWD'),...saved}:currencyDefaults());
}catch{fill(currencyDefaults());}
try{db=await openDB();dataset=await dbGet();if(dataset){dataset.stats??=null;dataSummary();}}catch{err('本機儲存不可用；上傳資料僅保留在本次頁面。');}
dataSummary();sync();
